internal final class AVAChargeSpecificationTransferProcess extends NDXTransferToD365 implements NDXTransferToD365Interface
{
    AVAChargeSpecification lAVAChargeSpecification;
    Niedax.AX.TableRecordModels.AVAChargeSpecification chargeSpecificationTable;

}

Method.Source:
public void new()
{
    super();
    chargeSpecificationTable = new Niedax.AX.TableRecordModels.AVAChargeSpecification();
    chargeSpecificationTable.D365ClassId = classIdGet(this);
    chargeSpecificationTable.D365ClassName = classId2Name(chargeSpecificationTable.D365ClassId);
}

/// <summary>
/// Class entry point. The system will call this method when a designated menu
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public void startTransfer(Args _args)
{
    super(_args);

    while select crosscompany lAVAChargeSpecification
    {
        chargeSpecificationTable.AccountCode = enum2Symbol(enumNum(TableGroupAll), lAVAChargeSpecification.AccountCode);
        chargeSpecificationTable.AccountRelation = lAVAChargeSpecification.AccountRelation;
        chargeSpecificationTable.CalcQty = lAVAChargeSpecification.CalcQty;
        chargeSpecificationTable.CalculationUnit = lAVAChargeSpecification.CalculationUnit;
        chargeSpecificationTable.Charge = lAVAChargeSpecification.Charge;
        chargeSpecificationTable.ChargeType = enum2Symbol(enumNum(AVAChargeType), lAVAChargeSpecification.ChargeType);
        chargeSpecificationTable.CurrencyCode = lAVAChargeSpecification.CurrencyCode;
        chargeSpecificationTable.DataAreaId = lAVAChargeSpecification.DataAreaId;
        chargeSpecificationTable.FromDate = lAVAChargeSpecification.FromDate;

        chargeSpecificationTable.GRUpdate = enum2Symbol(enumNum(NoYes),lAVAChargeSpecification.GRUpdate);
        chargeSpecificationTable.ItemCode = enum2Symbol(enumNum(TableGroupAll), lAVAChargeSpecification.ItemCode);
        chargeSpecificationTable.ItemRelation = lAVAChargeSpecification.ItemRelation;
        chargeSpecificationTable.PriceUnit = lAVAChargeSpecification.PriceUnit;

        chargeSpecificationTable.D365TableId = tableNum(AVAChargeSpecification);
        chargeSpecificationTable.D365TableName = tableId2PName(chargeSpecificationTable.D365TableId);

        try
        {
            response = tableTransfer.transferTableRecordToD365(chargeSpecificationTable);
        }
        catch
        {
            response.Message = strFmt('transfer exception %1 ', chargeSpecificationTable.ToString());
        }

        this.dispTransferInfo();
    }
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    chargeSpecificationTable = _record;
    lAVAChargeSpecification.clear();

    response.Message = strFmt("%1 %2 not created on %3", chargeSpecificationTable.D365TableName
                    , chargeSpecificationTable.ToString()
                    , this.environment);

    changecompany(chargeSpecificationTable.DataAreaId)
    {
        ttsbegin;
        lAVAChargeSpecification = AVAChargeSpecification::find(symbol2Enum(enumNum(TableGroupAll),chargeSpecificationTable.AccountCode),
                                            chargeSpecificationTable.AccountRelation,
                                            symbol2Enum(enumNum(TableGroupAll),chargeSpecificationTable.ItemCode),
                                            chargeSpecificationTable.ItemRelation,
                                            symbol2Enum(enumNum(AVAChargeType),chargeSpecificationTable.ChargeType),
                                            chargeSpecificationTable.FromDate, true);

        lAVAChargeSpecification.AccountCode = symbol2Enum(enumNum(TableGroupAll),chargeSpecificationTable.AccountCode);
        lAVAChargeSpecification.AccountRelation = chargeSpecificationTable.AccountRelation;
        lAVAChargeSpecification.CalcQty = chargeSpecificationTable.CalcQty;
        lAVAChargeSpecification.CalculationUnit = chargeSpecificationTable.CalculationUnit;
        lAVAChargeSpecification.Charge = chargeSpecificationTable.Charge;
        lAVAChargeSpecification.ChargeType = symbol2Enum(enumNum(AVAChargeType),chargeSpecificationTable.ChargeType);

        lAVAChargeSpecification.CurrencyCode = chargeSpecificationTable.CurrencyCode;
        lAVAChargeSpecification.FromDate =  chargeSpecificationTable.FromDate;

        lAVAChargeSpecification.GRUpdate = symbol2Enum(enumNum(NoYes),chargeSpecificationTable.GRUpdate);
        lAVAChargeSpecification.ItemCode = symbol2Enum(enumNum(TableGroupAll),chargeSpecificationTable.ItemCode);
        lAVAChargeSpecification.ItemRelation = chargeSpecificationTable.ItemRelation;

        lAVAChargeSpecification.PriceUnit = chargeSpecificationTable.PriceUnit;
        lAVAChargeSpecification.write();
        ttscommit;

        if(lAVAChargeSpecification)
        {
            response.Success = true;
            response.Message = strFmt("%1 %2 created on %3", chargeSpecificationTable.D365TableName
                    , chargeSpecificationTable.ToString()
                    , this.environment);
        }
    }

    response.RecId = lAVAChargeSpecification.RecId;

    return response;
}
